+  if (type.isF64())
+    return NVVM::MMATypes::f64;
+  if (type.isInteger(8))
+    return NVVM::MMATypes::s8;
+  if (isa<Float8E5M2Type>(type))
+    return NVVM::MMATypes::e5m2;
+  if (isa<Float8E4M3FNType>(type))
+    return NVVM::MMATypes::e4m3;
+  llvm_unreachable("unsupported MMA operand type");
